#include "stdlib/math/base/special/trunc10f.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/log10.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"

/**
* Rounds a single-precision floating point number to the nearest power of `10` toward zero.
*
* @param x    input value
* @return     rounded value
*
* @example
* float y = stdlib_base_trunc10f( 13.0 );
* // returns 10.0
*/
float stdlib_base_trunc10f( const float x ) {
	float sign;
	float xc;

	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) || x == 0.0f ) {
		return x;
	}
	xc = x;
	if( xc < 0.0f ) {
		xc = -xc;
		sign = -1.0f;
	} else {
		sign = 1.0f;
	}
	return sign * stdlib_base_powf( 10.0f, stdlib_base_floorf( stdlib_base_log10( xc ) ) );
}
